import{_ as t,a0 as o,w as d,s as r,ao as l,I as p,x as s,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"如何在 RHEL 上通過綁定配置 VLAN 標記 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 上通過綁定配置 VLAN 標記 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 上通過綁定配置 VLAN 標記 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 上通過綁定配置 VLAN 標記 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20230907 How to Configure VLAN Tagging Over Bonding on RHEL","title":"如何在 RHEL 上通過綁定配置 VLAN 標記","tag":"202401","desc":""},"relativePath":"202401/20230907 How to Configure VLAN Tagging Over Bonding on RHEL.md","filePath":"[post].md"}'),c={name:"202401/20230907 How to Configure VLAN Tagging Over Bonding on RHEL.md"};function h(g,a,b,k,f,u){const n=o("Link");return d(),r("div",null,[a[18]||(a[18]=l(`<h1 id="如何在-rhel-上通過綁定配置-vlan-標記" tabindex="-1">如何在 RHEL 上通過綁定配置 VLAN 標記 <a class="header-anchor" href="#如何在-rhel-上通過綁定配置-vlan-標記" aria-label="Permalink to “如何在 RHEL 上通過綁定配置 VLAN 標記”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202401/30/154618igt5zj2dwgfax2th.jpg" alt=""></p><p>在 Linux 中，你可以根據自己的需要創建高級網絡設置，如 <ruby>網絡綁定<rt>Network Bonding</rt></ruby> 或 <ruby>網卡聚合<rt>NIC teaming</rt></ruby>、VLAN 標記和橋接。這些高級功能可以提高網絡連接的效率和可靠性。</p><p>你可以在以太網、綁定、聚合或橋接設備等其他接口上創建 VLAN 接口。</p><p>在本文中，我們將學習如何在 RHEL 系統中通過網絡綁定配置 VLAN 標記，它允許來自不同網絡的流量共享共同的物理鏈接。</p><h3 id="通過綁定對-vlan-進行標記的先決條件" tabindex="-1">通過綁定對 VLAN 進行標記的先決條件 <a class="header-anchor" href="#通過綁定對-vlan-進行標記的先決條件" aria-label="Permalink to “通過綁定對 VLAN 進行標記的先決條件”">​</a></h3><ul><li>網絡聚合需要在網絡交換機端口上啓用 LACP（802.3ad），以聚合鏈路。</li><li>網絡聚合需要將網絡端口配置為中繼端口，這樣可以在同一端口上添加多個 VLAN。此外，還要從它們那裏獲取 VLAN ID，以便在操作系統層面進行配置。</li><li>Linux 系統應該有兩個接口。</li><li>如果是物理服務器，我們建議在板載接口和 PCI 接口之間配置綁定，以避免主機端的網卡出現單點故障。</li></ul><h4 id="綁定內核模組" tabindex="-1">綁定內核模組 <a class="header-anchor" href="#綁定內核模組" aria-label="Permalink to “綁定內核模組”">​</a></h4><p>使用 <code>lsmod</code> 命令檢查 Linux 系統是否已加載綁定模組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsmod | grep -i bonding</span></span>
<span class="line"><span>bonding 12451 0</span></span></code></pre></div><p>默認情況下已加載。否則，請使用 <code>modprobe</code> 命令加載它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>modprobe bonding</span></span></code></pre></div><h3 id="_1-lacp-綁定配置" tabindex="-1">1) LACP 綁定配置 <a class="header-anchor" href="#_1-lacp-綁定配置" aria-label="Permalink to “1) LACP 綁定配置”">​</a></h3><p>我們將配置基於 LACP（Mode 4 – 802.3ad）的鏈路聚合綁定，通過組合名為 <code>em1</code> 和 <code>p7p1</code> 的兩個接口，為綁定接口提供更大的帶寬。</p><h4 id="_1a-創建-bond-接口" tabindex="-1">1a) 創建 Bond 接口 <a class="header-anchor" href="#_1a-創建-bond-接口" aria-label="Permalink to “1a) 創建 Bond 接口”">​</a></h4><p>在目錄 <code>/etc/sysconfig/network-scripts/</code> 下創建綁定接口文件 <code>ifcfg-bond0</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-bond0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TYPE=Bond</span></span>
<span class="line"><span>DEVICE=bond0</span></span>
<span class="line"><span>NAME=bond0</span></span>
<span class="line"><span>BONDING_MASTER=yes</span></span>
<span class="line"><span>BOOTPROTO=none</span></span>
<span class="line"><span>ONBOOT=yes</span></span>
<span class="line"><span>BONDING_OPTS=&quot;mode=4 miimon=100 lacp_rate=1&quot;</span></span>
<span class="line"><span>NM_CONTROLLED=no</span></span></code></pre></div><h4 id="_1b-配置第一個從接口" tabindex="-1">1b) 配置第一個從接口 <a class="header-anchor" href="#_1b-配置第一個從接口" aria-label="Permalink to “1b) 配置第一個從接口”">​</a></h4><p>配置你想要進行綁定的第一個從屬接口 <code>em1</code>。請根據你的環境使用正確的接口名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-em1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TYPE=Ethernet</span></span>
<span class="line"><span>BOOTPROTO=none</span></span>
<span class="line"><span>DEVICE=em1</span></span>
<span class="line"><span>ONBOOT=yes</span></span>
<span class="line"><span>MASTER=bond0</span></span>
<span class="line"><span>SLAVE=yes</span></span></code></pre></div><h4 id="_1c-配置第二個從接口" tabindex="-1">1c) 配置第二個從接口 <a class="header-anchor" href="#_1c-配置第二個從接口" aria-label="Permalink to “1c) 配置第二個從接口”">​</a></h4><p>配置你想要進行綁定的第二個從屬接口 <code>p7p1</code>。 請根據你的環境使用正確的接口名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-p7p1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TYPE=Ethernet</span></span>
<span class="line"><span>BOOTPROTO=none</span></span>
<span class="line"><span>DEVICE=p7p1</span></span>
<span class="line"><span>ONBOOT=yes</span></span>
<span class="line"><span>MASTER=bond0</span></span>
<span class="line"><span>SLAVE=yes</span></span></code></pre></div><h4 id="重啓網絡服務" tabindex="-1">重啓網絡服務 <a class="header-anchor" href="#重啓網絡服務" aria-label="Permalink to “重啓網絡服務”">​</a></h4><p>重啓網絡服務以啓用綁定接口或使用 <code>ifup</code> 命令啓動它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart network</span></span></code></pre></div><h3 id="_2-通過綁定接口進行-vlan-標記" tabindex="-1">2) 通過綁定接口進行 VLAN 標記 <a class="header-anchor" href="#_2-通過綁定接口進行-vlan-標記" aria-label="Permalink to “2) 通過綁定接口進行 VLAN 標記”">​</a></h3><p>LACP 綁定配置已完成，所有接口現已啓動並運行。讓我們按照以下步驟配置綁定接口上的 VLAN 標記。</p><p>正如先決條件中所討論的，以下是映射到相應以太網卡端口（<code>em1</code> 和 <code>p7p1</code>）和網絡交換機端口的 VLAN。</p><ul><li>VLAN ID (221), VLAN N/W = 192.168.10.0/24</li><li>VLAN ID (331), VLAN N/W = 192.168.20.0/24</li></ul><h4 id="_2a-將-vlan-221-配置到-bond0" tabindex="-1">2a) 將 VLAN 221 配置到 Bond0 <a class="header-anchor" href="#_2a-將-vlan-221-配置到-bond0" aria-label="Permalink to “2a) 將 VLAN 221 配置到 Bond0”">​</a></h4><p>為 VLAN id 221 創建標記接口文件 <code>/etc/sysconfig/network-scripts/ifcfg-bond0.221</code> 並添加以下內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-bond0.221</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DEVICE=bond0.221</span></span>
<span class="line"><span>BOOTPROTO=none</span></span>
<span class="line"><span>ONBOOT=yes</span></span>
<span class="line"><span>IPADDR=192.168.10.100</span></span>
<span class="line"><span>NETMASK=255.255.255.0</span></span>
<span class="line"><span>GATEWAY=192.168.10.1</span></span>
<span class="line"><span>VLAN=yes</span></span>
<span class="line"><span>NM_CONTROLLED=no</span></span></code></pre></div><h4 id="_2b-將-vlan-331-配置到-bond0" tabindex="-1">2b) 將 VLAN 331 配置到 Bond0 <a class="header-anchor" href="#_2b-將-vlan-331-配置到-bond0" aria-label="Permalink to “2b) 將 VLAN 331 配置到 Bond0”">​</a></h4><p>為 VLAN id 331 創建標記接口文件 <code>/etc/sysconfig/network-scripts/ifcfg-bond0.331</code> 並添加以下內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/sysconfig/network-scripts/ifcfg-bond0.331</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DEVICE=bond0.331</span></span>
<span class="line"><span>BOOTPROTO=none</span></span>
<span class="line"><span>ONBOOT=yes</span></span>
<span class="line"><span>IPADDR=192.168.20.100</span></span>
<span class="line"><span>NETMASK=255.255.255.0</span></span>
<span class="line"><span>GATEWAY=192.168.20.1</span></span>
<span class="line"><span>VLAN=yes</span></span>
<span class="line"><span>NM_CONTROLLED=no</span></span></code></pre></div><h4 id="重啓網絡服務-1" tabindex="-1">重啓網絡服務 <a class="header-anchor" href="#重啓網絡服務-1" aria-label="Permalink to “重啓網絡服務”">​</a></h4><p>重啓網絡服務以啓用綁定接口或使用 <code>ifup</code> 命令啓動它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart network</span></span></code></pre></div><h3 id="驗證-vlan-標記配置" tabindex="-1">驗證 VLAN 標記配置 <a class="header-anchor" href="#驗證-vlan-標記配置" aria-label="Permalink to “驗證 VLAN 標記配置”">​</a></h3>`,40)),p("p",null,[a[1]||(a[1]=s("最後使用 ",-1)),e(n,{href:"https://www.2daygeek.com/linux-ip-command-configure-network-interface/"},{default:i(()=>[...a[0]||(a[0]=[s("ip 命令",-1)])]),_:1}),a[2]||(a[2]=s(" 驗證 VLAN 標記接口是否已配置並啓動和運行。",-1))]),a[19]||(a[19]=l('<p>是的，我可以看到 <code>bondo.221@bond0</code> 和 <code>bon0.331@bond0</code> 有兩個不同的 IP，並且能夠通過 ssh 訪問系統，沒有任何問題。因此，VLAN 標記按預期工作。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2023/09/configure-vlan-tagging-over-bonding-rhel-1024x395.jpg" alt=""></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>恭喜，你已經瞭解瞭如何在 RHEL 系統上通過 LACP 綁定配置 VLAN 標記，該系統監聽兩個 VLAN。VLAN 標記不限於兩個 VLAN，支持多個 VLAN，你可以根據該 VLAN 的網絡配置添加 VLAN 標記。</p><p><em>（題圖：DA/2854516d-4d19-4008-a421-05f9a2a78368）</em></p><hr>',6)),p("p",null,[a[4]||(a[4]=s("via: ",-1)),e(n,{href:"https://www.2daygeek.com/configure-vlan-tagging-over-network-bonding-rhel/"},{default:i(()=>[...a[3]||(a[3]=[s("https://www.2daygeek.com/configure-vlan-tagging-over-network-bonding-rhel/",-1)])]),_:1})]),p("p",null,[a[9]||(a[9]=s("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/jayabal/"},{default:i(()=>[...a[5]||(a[5]=[s("Jayabal Thiyagarajan",-1)])]),_:1}),a[10]||(a[10]=s(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[6]||(a[6]=[s("lujun9972",-1)])]),_:1}),a[11]||(a[11]=s(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...a[7]||(a[7]=[s("geekpi",-1)])]),_:1}),a[12]||(a[12]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...a[8]||(a[8]=[s("wxy",-1)])]),_:1})]),p("p",null,[a[15]||(a[15]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...a[14]||(a[14]=[s("Linux中國",-1)])]),_:1}),a[17]||(a[17]=s(" 榮譽推出",-1))])])}const A=t(c,[["render",h]]);export{N as __pageData,A as default};
